// ---------- geometry helpers ----------
function ring(cx,cy,rx,ry,irx,iry){
  return `M${cx-rx} ${cy} A${rx} ${ry} 0 1 0 ${cx+rx} ${cy} A${rx} ${ry} 0 1 0 ${cx-rx} ${cy} Z M${cx-irx} ${cy} A${irx} ${iry} 0 1 1 ${cx+irx} ${cy} A${irx} ${iry} 0 1 1 ${cx-irx} ${cy} Z`;
}
function oval(cx,cy,rx,ry){return `M${cx-rx} ${cy} A${rx} ${ry} 0 1 0 ${cx+rx} ${cy} A${rx} ${ry} 0 1 0 ${cx-rx} ${cy} Z`;}

